const colorFor=c=>({ALTA:'#7c3aed',MEDIA:'#f59e0b',BAIXA:'#ef4444',SEM_REFERENCIA:'#64748b'})[c]||'#38bdf8';
const fireColor=c=>({URGENTE:'#dc2626',ATENCAO:'#f59e0b',MONITORAMENTO:'#16a34a'})[(c||'').toUpperCase()]||'#64748b';
const energyColor=n=>({CRITICO:'#dc2626',ALTO:'#ea580c',ATENCAO:'#f59e0b',BAIXO:'#0ea5e9',MONITORAMENTO:'#64748b'})[(n||'').toUpperCase()]||'#64748b';
const weatherColor=c=>({CRITICO:'#dc2626',ALTO:'#ea580c',ATENCAO:'#f59e0b',MONITORAMENTO:'#0ea5e9'})[(c||'').toUpperCase()]||'#64748b';
const norm=v=>(v??'').toString().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();
const esc=v=>(v??'—').toString().replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmtKm=v=>Number.isFinite(Number(v))?`${Number(v).toFixed(3)} km`:'—';
const windCompass=d=>{const n=Number(d);if(!Number.isFinite(n))return '—';const pts=['N','NE','L','SE','S','SO','O','NO'];return `${pts[Math.round((((n%360)+360)%360)/45)%8]} (${Math.round(n)}°)`;};
const weatherCodeLabel=c=>({0:'Céu limpo',1:'Predom. limpo',2:'Parcialmente nublado',3:'Nublado',45:'Nevoeiro',48:'Nevoeiro com geada',51:'Garoa leve',53:'Garoa',55:'Garoa forte',61:'Chuva leve',63:'Chuva',65:'Chuva forte',71:'Neve leve',73:'Neve',75:'Neve forte',80:'Pancadas leves',81:'Pancadas',82:'Pancadas fortes',95:'Tempestade',96:'Tempestade c/ granizo',99:'Tempestade forte c/ granizo'})[Number(c)]||'Condição meteorológica';
function forecastHtml(e){const ph=Array.isArray(e.previsao_horaria)?e.previsao_horaria:[];if(!ph.length)return '<div class="forecast-empty">Previsão horária ainda não disponível para este município.</div>';return `<div class="forecast-grid">${ph.slice(0,8).map(x=>{const dt=x.data_hora?new Date(x.data_hora):null;const hh=dt&&!Number.isNaN(dt.getTime())?dt.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):(x.data_hora||'—');return `<div class="forecast-card ${x.tempestade?'forecast-storm':''}"><b>${esc(hh)}</b><span>${esc(weatherCodeLabel(x.weather_code))}</span><span>💨 ${esc(x.vento_kmh)} km/h • ${esc(windCompass(x.direcao_vento_graus))}</span><span>🌬️ raj. ${esc(x.rajada_kmh)} km/h</span><span>🌧️ ${esc(x.precipitacao_mm)} mm • ${esc(x.probabilidade_chuva)}%</span>${x.tempestade?'<strong>⚡ Tempestade prevista</strong>':''}</div>`}).join('')}</div>`;}

function popupHtml(p){return `<b>${esc(p.trecho||'Backbone')}</b><br>${esc(p.ponta_a)} — ${esc(p.municipio_a)}<br>${esc(p.ponta_b)} — ${esc(p.municipio_b)}<br>Cabo: <b>${esc(p.cabo)}</b><br>Confiança: ${esc(p.confianca)}`;}
function detailsHtml(p){const rows=[['Trecho',p.trecho],['Cabo',p.cabo],['Capacidade',p.capacidade],['Cluster',p.cluster],['Ponta A',`${p.ponta_a||'—'} — ${p.municipio_a||'—'}`],['Ponta B',`${p.ponta_b||'—'} — ${p.municipio_b||'—'}`],['Extensão',p.extensao_km?`${Number(p.extensao_km).toFixed(2)} km`:'—'],['Confiança',p.confianca],['Fonte',p.fonte]];return `<div class="panel-title">Trecho selecionado</div><h3>${esc(p.trecho||'Backbone')}</h3>${rows.map(r=>`<div class="row"><span>${esc(r[0])}</span><span>${esc(r[1]??'—')}</span></div>`).join('')}`;}

function render(){const cl=document.getElementById('clusterFilter').value,cf=document.getElementById('confidenceFilter').value,q=norm(document.getElementById('searchBox').value);const feats=allFeatures.filter(f=>{const p=f.properties||{};if(cl&&p.cluster!==cl)return false;if(cf&&p.confianca!==cf)return false;if(q&&!norm([p.trecho,p.cabo,p.cluster,p.ponta_a,p.ponta_b,p.municipio_a,p.municipio_b].join(' ')).includes(q))return false;return true;});if(layer)layer.remove();layer=L.geoJSON({type:'FeatureCollection',features:feats},{style:f=>({color:colorFor(f.properties.confianca),weight:3,opacity:.78}),onEachFeature:(f,l)=>{l.bindPopup(popupHtml(f.properties));l.on('click',()=>document.getElementById('details').innerHTML=detailsHtml(f.properties));l.on('mouseover',()=>l.setStyle({weight:6,opacity:1}));l.on('mouseout',()=>layer.resetStyle(l));}}).addTo(map);document.getElementById('rotas').textContent=feats.length.toLocaleString('pt-BR');if(feats.length&&q)try{map.fitBounds(layer.getBounds(),{padding:[20,20],maxZoom:12})}catch(e){}}
function populate(){const ps=allFeatures.map(f=>f.properties||{});const uniq=k=>[...new Set(ps.map(p=>p[k]).filter(Boolean))];document.getElementById('clusters').textContent=uniq('cluster').length;document.getElementById('cabos').textContent=uniq('cabo').length;document.getElementById('municipios').textContent=new Set(ps.flatMap(p=>[p.municipio_a,p.municipio_b]).filter(Boolean)).size;const s=document.getElementById('clusterFilter');uniq('cluster').sort().forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;s.appendChild(o)});render();}

function firePopupHtml(e){return `<div class="fire-popup"><b style="color:${fireColor(e.classificacao)}">🔥 ${esc(e.classificacao)}</b><br><b>${esc(e.id_evento)}</b><br>Município: ${esc(e.municipio)}<br>Última detecção: ${esc(e.ultima_deteccao)}<br>Backbone: <b>${esc(e.backbone)}</b><br>Cabo: ${esc(e.cabo)}<br>Distância: <b>${fmtKm(e.distancia_backbone_km)}</b><br>Confiança: ${esc(e.confianca_rota)}<br>Satélite: ${esc(e.satelite)}<br>Detecções: ${esc(e.deteccoes)}</div>`;}
function fireDetailsHtml(e){const rows=[['Classificação',e.classificacao],['Evento',e.id_evento],['Município',e.municipio],['Última detecção',e.ultima_deteccao],['Backbone',e.backbone],['Cabo',e.cabo],['Distância',fmtKm(e.distancia_backbone_km)],['Confiança',e.confianca_rota],['Satélite',e.satelite],['Detecções',e.deteccoes]];return `<div class="panel-title">🔥 Fire Core</div><h3 class="fire-title" style="color:${fireColor(e.classificacao)}">${esc(e.classificacao)}</h3>${rows.map(r=>`<div class="row"><span>${esc(r[0])}</span><span>${esc(r[1]??'—')}</span></div>`).join('')}`;}
function highlightBackbone(e){relatedBackboneLayer.clearLayers();const f=allFeatures.find(x=>{const p=x.properties||{};return (e.id_backbone&&p.id_backbone===e.id_backbone)||(e.backbone&&p.trecho===e.backbone);});if(!f)return;L.geoJSON(f,{style:{color:fireColor(e.classificacao),weight:8,opacity:1}}).addTo(relatedBackboneLayer).bringToFront();}
function renderFire(){fireLayer.clearLayers();relatedBackboneLayer.clearLayers();let selectedMarker=null,selectedEvent=null;const enabled=document.getElementById('fireToggle')?.checked!==false;document.getElementById('fireCount').textContent=`${fireEvents.length} ativo${fireEvents.length===1?'':'s'}`;if(!enabled)return;fireEvents.forEach(e=>{const lat=Number(e.latitude),lon=Number(e.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))return;const color=fireColor(e.classificacao);const fireFocus=document.getElementById('fireView')&&!document.getElementById('fireView').hidden;const selected=selectedFireId===e.id_evento,dimmed=selectedFireId&&!selected;const marker=L.circleMarker([lat,lon],{radius:selected?27:(fireFocus?20:11),color:selected?'#fff':'#e2e8f0',weight:selected?5:(fireFocus?3:2),fillColor:color,fillOpacity:dimmed?.18:.97,opacity:dimmed?.28:1,className:selected?'fire-marker-selected':(fireFocus?'fire-marker-focus':'')});marker.bindPopup(firePopupHtml(e)+`<div class="fire-popup-more">${fireDetailsHtml(e)}</div>`,{maxWidth:380,autoPan:true,autoPanPadding:[30,30]});marker.bindTooltip(`🔥 ${e.classificacao||'FIRE'} • ${e.id_evento||''}`);marker.on('click',()=>{selectedFireId=e.id_evento;document.getElementById('details').innerHTML=fireDetailsHtml(e);renderFire();map.flyTo([lat,lon],Math.max(map.getZoom(),10),{duration:.45});});marker.addTo(fireLayer);if(selected){selectedMarker=marker;selectedEvent=e}const p=e.ponto_mais_proximo||{};const plat=Number(p.latitude),plon=Number(p.longitude);if(Number.isFinite(plat)&&Number.isFinite(plon)){L.polyline([[lat,lon],[plat,plon]],{color,weight:3,opacity:.85,dashArray:'8 8'}).addTo(fireLayer);L.circleMarker([plat,plon],{radius:5,color,weight:2,fillColor:'#fff',fillOpacity:1}).addTo(fireLayer);}});if(selectedEvent){highlightBackbone(selectedEvent);setTimeout(()=>{try{selectedMarker?.openPopup()}catch(e){}},20)}}


function energyPopupHtml(e){const ds=(e.distribuidoras||[]).join(', ')||'—';const st=(e.status||[]).join(', ')||'—';return `<div class="energy-popup"><b style="color:${energyColor(e.nivel)}">⚡⧸ SEM ENERGIA</b><br><b>${esc(e.regiao)}</b><br>${esc(e.municipio)}<br>Distribuidora: ${esc(ds)}<br>Status: ${esc(st)}<br>Ocorrências: ${(e.ocorrencias||[]).length}</div>`;}
function energyDetailsHtml(e){const rows=[['Condição','SEM ENERGIA'],['Região',e.regiao],['Município',e.municipio],['Distribuidora(s)',(e.distribuidoras||[]).join(', ')||'—'],['Status',(e.status||[]).join(', ')||'—'],['Ocorrência(s)',(e.ocorrencias||[]).join(', ')||'—'],['Referência geográfica',e.origem_coordenada],['Confiança',e.confianca_geografica]];return `<div class="panel-title">⚡ Energia</div><h3 class="energy-title" style="color:${energyColor(e.nivel)}">⚡⧸ ${esc(e.regiao)}</h3>${rows.map(r=>`<div class="row"><span>${esc(r[0])}</span><span>${esc(r[1]??'—')}</span></div>`).join('')}`;}
function energyIcon(e){const z=map.getZoom();const compact=z<=7;const size=compact?8:11;return L.divIcon({className:'energy-outage-wrapper',html:`<div class="energy-outage-icon ${compact?'energy-compact':''}"><span class="energy-bolt"></span><span class="energy-slash"></span></div>`,iconSize:[size,size],iconAnchor:[size/2,size/2],popupAnchor:[0,-8]});}
function renderEnergy(){energyLayer.clearLayers();const enabled=document.getElementById('energyToggle')?.checked!==false;const count=document.getElementById('energyCount');if(count)count.textContent=`${energyEvents.length} região${energyEvents.length===1?'':'ões'}`;if(!enabled)return;energyEvents.forEach(e=>{const lat=Number(e.latitude),lon=Number(e.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))return;const marker=L.marker([lat,lon],{icon:energyIcon(e),zIndexOffset:700});marker.bindPopup(energyPopupHtml(e));marker.bindTooltip(`⚡⧸ ${e.regiao||''} • ${e.municipio||''}`);marker.on('click',()=>{document.getElementById('details').innerHTML=energyDetailsHtml(e);if(document.getElementById('mapView')?.classList.contains('mobile-focus-mode'))renderMobileIntel(e);});marker.addTo(energyLayer);});}
async function loadEnergy(){try{const r=await fetch(`${ENERGY_DATA}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`Energy HTTP ${r.status}`);const obj=await r.json();energyEvents=Array.isArray(obj.regioes)?obj.regioes:[];renderEnergy();renderMobileFocus();const c=document.getElementById('energyCount');if(c)c.title=obj.gerado_em?`Atualizado: ${obj.gerado_em}`:'Energy Core';}catch(err){console.error('Falha Energy Core',err);const c=document.getElementById('energyCount');if(c)c.textContent='erro';}}
async function loadFire(){try{const r=await fetch(`${FIRE_DATA}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`Fire HTTP ${r.status}`);const obj=await r.json();fireEvents=Array.isArray(obj.eventos_ativos)?obj.eventos_ativos:[];renderFire();renderFireFocus();if(ribeiraoMode&&ribeiraoPolygon)ribeiraoRenderFire();document.getElementById('fireCount').title=obj.gerado_em?`Atualizado: ${obj.gerado_em}`:'Fire Core';}catch(err){console.error('Falha Fire Core',err);document.getElementById('fireCount').textContent='erro';}}

function fireHistoryAgeHours(e){const t=new Date(e.ultima_deteccao_utc||e.primeira_deteccao_utc||0).getTime();return Number.isFinite(t)?(Date.now()-t)/3600000:Infinity}
function fireHistoryColor(e){return({CRITICA:'#dc2626',ALTA:'#f97316',ATENCAO:'#f59e0b',MONITORAMENTO:'#16a34a'})[norm(e.classificacao_proximidade)]||'#64748b'}
function fireHistoryPopupHtml(e){return `<div class="fire-popup"><b style="color:${fireHistoryColor(e)}">🔥 HISTÓRICO • ${esc(e.classificacao_proximidade||'FIRE')}</b><br><b>${esc(e.id_evento)}</b><br>Status: ${esc(e.status)}<br>Município ref.: <b>${esc(e.municipio)}</b><br>Última detecção: ${esc(e.ultima_deteccao_utc?new Date(e.ultima_deteccao_utc).toLocaleString('pt-BR'):'—')}<br>Detecções: ${esc(e.quantidade_deteccoes)} • Reativações: ${esc(e.quantidade_reativacoes)}<br>Site mais próximo: ${esc(e.site_mais_proximo)} • ${Number.isFinite(Number(e.menor_distancia_site_km))?Number(e.menor_distancia_site_km).toFixed(1)+' km':'—'}<br>Sites ≤4h: ${esc(e.sites_ate_4h)}<br>Satélite(s): ${esc((e.satelites||[]).join(', '))}</div>`}
function renderFireHistory(){fireHistoryLayer.clearLayers();const inFire=document.getElementById('mapView')?.classList.contains('fire-focus-mode');if(!inFire)return;const recent=fireHistoryEvents.filter(e=>fireHistoryAgeHours(e)>=0&&fireHistoryAgeHours(e)<=24);for(const e of recent){const lat=Number(e.latitude),lon=Number(e.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))continue;const c=fireHistoryColor(e),m=L.circleMarker([lat,lon],{radius:8,color:c,weight:2,fillColor:c,fillOpacity:.28,opacity:.72,dashArray:'4 3'});m.bindPopup(fireHistoryPopupHtml(e));m.bindTooltip(`🔥 Histórico • ${e.municipio||e.id_evento||''} • ${e.quantidade_deteccoes||0} det.`);m.addTo(fireHistoryLayer)}}
function renderFireHistoryPanel(){const total=document.getElementById('fireHistoryTotal'),h24=document.getElementById('fireHistory24h'),list=document.getElementById('fireHistoryList');if(!total||!h24||!list)return;const r24=fireHistoryEvents.filter(e=>fireHistoryAgeHours(e)>=0&&fireHistoryAgeHours(e)<=24);total.textContent=fireHistoryEvents.length.toLocaleString('pt-BR');h24.textContent=r24.length.toLocaleString('pt-BR');const latest=[...fireHistoryEvents].sort((a,b)=>new Date(b.ultima_deteccao_utc||0)-new Date(a.ultima_deteccao_utc||0)).slice(0,8);list.innerHTML=latest.length?latest.map(e=>`<button class="fire-history-row" data-fire-history="${esc(e.id_evento)}"><b>${esc(e.municipio||e.id_evento)}</b><span>${e.ultima_deteccao_utc?new Date(e.ultima_deteccao_utc).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'} • ${esc(e.quantidade_deteccoes)} det. • ${esc(e.classificacao_proximidade||'—')}</span></button>`).join(''):'<small>Histórico ainda não disponível.</small>';list.querySelectorAll('[data-fire-history]').forEach(b=>b.onclick=()=>{const e=fireHistoryEvents.find(x=>x.id_evento===b.dataset.fireHistory);if(!e)return;const lat=Number(e.latitude),lon=Number(e.longitude);if(Number.isFinite(lat)&&Number.isFinite(lon))map.flyTo([lat,lon],10,{duration:.5})})}
async function loadFireHistory(){try{const r=await fetch(`${FIRE_HISTORY_DATA}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`Fire history HTTP ${r.status}`);const o=await r.json();fireHistoryEvents=Array.isArray(o.eventos)?o.eventos:[];renderFireHistory();renderFireHistoryPanel();if(ribeiraoMode&&ribeiraoPolygon)ribeiraoRenderFire()}catch(e){console.error('Falha histórico Fire',e)}}


const climateSeverityRank=n=>({CRITICO:4,ALTO:3,ATENCAO:2,MONITORAMENTO:1})[norm(n)]||1;
function climateEventType(e){const rain=Number(e.chuva_total_mm||0),gust=Number(e.rajada_kmh||0);if(e.tempestade)return 'Tempestade';if(rain>=10&&gust>=45)return 'Chuva + rajada';if(rain>=10)return 'Chuva';if(gust>=45)return 'Rajada';return e.descricao||'Ameaça climática';}
function climateIsRelevant(e){const level=norm(e.nivel_risco),rain=Number(e.chuva_total_mm||0),gust=Number(e.rajada_kmh||0);return Boolean(e.ameaca_ativa)||Boolean(e.tempestade)||['CRITICO','ALTO','ATENCAO'].includes(level)||rain>=10||gust>=45;}
function climateOfficialMunicipios(){return new Set(defesaEvents.map(e=>norm(e.municipio)).filter(Boolean));}
function climateSortedEvents(){const dc=climateOfficialMunicipios();let base=weatherEvents.filter(climateIsRelevant);if(ribeiraoMode)base=base.filter(e=>norm(e.municipio)==='RIBEIRAO PRETO'||norm(e.regiao)==='RIBEIRAO PRETO');return base.sort((a,b)=>climateSeverityRank(b.nivel_risco)-climateSeverityRank(a.nivel_risco)||Number(Boolean(b.ameaca_ativa))-Number(Boolean(a.ameaca_ativa))||Number(dc.has(norm(b.municipio)))-Number(dc.has(norm(a.municipio)) )||Number(b.rajada_kmh||0)-Number(a.rajada_kmh||0)||Number(b.chuva_total_mm||0)-Number(a.chuva_total_mm||0)||Number(b.sites_ate_4h||0)-Number(a.sites_ate_4h||0)||Number(b.score_risco||0)-Number(a.score_risco||0));}
function climateStripItemHtml(e,dc){const official=dc.has(norm(e.municipio))||Boolean(e.alerta_oficial);const rain=Number.isFinite(Number(e.chuva_total_mm))?`${Number(e.chuva_total_mm).toFixed(1)} mm`:null;const gust=Number.isFinite(Number(e.rajada_kmh))?`${Number(e.rajada_kmh).toFixed(1)} km/h`:null;const exposed=Number.isFinite(Number(e.sites_total))?Number(e.sites_total):null;const low=Number.isFinite(Number(e.sites_ate_4h))?Number(e.sites_ate_4h):null;const parts=[`<b>${esc(e.municipio)}</b>`,`<span class="climate-level">${esc(e.nivel_risco||'MONITORAMENTO')}</span>`,`<span>${esc(climateEventType(e))}</span>`];if(rain!==null)parts.push(`<span>🌧️ ${esc(rain)}</span>`);if(gust!==null)parts.push(`<span>💨 ${esc(gust)}</span>`);if(exposed!==null)parts.push(`<span>📡 ${exposed} expostos</span>`);if(low!==null)parts.push(`<span>🔋 ${low} ≤4h</span>`);if(official){const ao=e.alerta_oficial||{},src=ao.fonte||'Defesa Civil',sev=ao.severidade?` • ${ao.severidade}`:'';parts.push(`<span class="climate-official">🚨 ${esc(src)}${esc(sev)}</span>`);}return `<button type="button" class="climate-strip-item" data-climate-municipio="${esc(e.municipio)}" title="Centralizar ${esc(e.municipio)} no mapa">${parts.join('<i>•</i>')}</button>`;}
function focusClimateMunicipio(name){const e=weatherEvents.find(x=>norm(x.municipio)===norm(name));if(!e)return;const lat=Number(e.latitude),lon=Number(e.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))return;map.setView([lat,lon],Math.max(map.getZoom(),10),{animate:true});document.getElementById('details').innerHTML=weatherDetailsHtml(e);}
function renderClimateStrip(){const strip=document.getElementById('climateStrip'),track=document.getElementById('climateStripTrack'),status=document.getElementById('climateStripStatus');if(!strip||!track||!status)return;const events=climateSortedEvents(),dc=climateOfficialMunicipios();const max=events.reduce((m,e)=>Math.max(m,climateSeverityRank(e.nivel_risco)),1),sev=max>=4?'critico':max>=3?'alto':max>=2?'atencao':'monitoramento';strip.className=`climate-strip severity-${sev}`;const rpOfficial=ribeiraoMode?defesaEvents.filter(e=>(norm(e.municipio)==='RIBEIRAO PRETO'||norm(e.regiao)==='RIBEIRAO PRETO')&&norm(e.status)==='ATIVO_OFICIAL').length:null;status.textContent=ribeiraoMode?(events.length?`Ribeirão Preto • ${events.length} relevante${events.length===1?'':'s'}${rpOfficial?` • ${rpOfficial} alerta(s) oficial(is)`:''}`:'Ribeirão Preto • monitoramento normal'):(events.length?`${events.length} relevante${events.length===1?'':'s'}${weatherMeta.alertas_oficiais_ativos!=null?` • ${weatherMeta.alertas_oficiais_ativos} alerta(s) oficial(is)`:''}`:'monitoramento normal');if(!events.length){track.className='climate-strip-track climate-strip-static';track.innerHTML=`<span class="climate-strip-empty">✅ ${ribeiraoMode?'Ribeirão Preto sem ameaças climáticas relevantes neste ciclo':'Sem ameaças climáticas relevantes neste ciclo'}</span>`;return;}const items=events.map(e=>climateStripItemHtml(e,dc)).join('');track.className='climate-strip-track';track.innerHTML=`<div class="climate-strip-run">${items}${items}</div>`;track.querySelectorAll('[data-climate-municipio]').forEach(b=>b.addEventListener('click',()=>focusClimateMunicipio(b.dataset.climateMunicipio)));}


const importantNormText=v=>norm(v).replace(/\s+/g,' ');
const IMPORTANT_OFFICIAL_MAX_AGE_H=3;
const importantWeatherCache=new Map();
function importantSitesFor(name){const k=norm(name);const groups={'LITORAL NORTE':['CARAGUATATUBA','SAO SEBASTIAO','UBATUBA','ILHABELA'],'OSASCO':['OSASCO'],'JUNDIAI':['JUNDIAI']};const names=groups[k]||[k];const arr=siteEvents.filter(x=>names.includes(norm(x.municipio)));return{total:arr.length,ate4h:arr.filter(siteIsCritical).length};}
function importantTimeFromSummary(txt){const m=(txt||'').match(/\b(\d{1,2})\s*[:hH]\s*(\d{2})?\b/);if(!m)return null;return `${String(m[1]).padStart(2,'0')}:${m[2]||'00'}`;}
function importantOfficialDate(e){const hm=importantTimeFromSummary(e.resumo||'');if(!hm)return null;const dm=String(e.vigencia||'').match(/(\d{2})\/(\d{2})\/(\d{4})/);if(!dm)return null;const iso=`${dm[3]}-${dm[2]}-${dm[1]}T${hm}:00-03:00`,d=new Date(iso);return Number.isNaN(d.getTime())?null:d;}
function importantOfficialAgeHours(e){const d=importantOfficialDate(e);return d?(Date.now()-d.getTime())/3600000:null;}
function importantOfficialCurrent(e){const age=importantOfficialAgeHours(e);if(age==null)return norm(e.gravidade)==='EXTREME';return age>=-0.5&&age<=IMPORTANT_OFFICIAL_MAX_AGE_H;}
function importantWeatherKey(e){return `${Number(e.latitude).toFixed(4)},${Number(e.longitude).toFixed(4)}`;}
async function refreshImportantWeather(){const cands=operationalDefesaEvents().filter(e=>norm(e.status)==='ATIVO_OFICIAL'&&importantOfficialCurrent(e)).filter(e=>{const t=importantNormText(e.resumo||'');return norm(e.gravidade)==='EXTREME'||t.includes('GRANIZO')||t.includes('RAIOS')||t.includes('CONDICAO PARA RAIOS')});const unique=[];const seen=new Set();for(const e of cands){const lat=Number(e.latitude),lon=Number(e.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))continue;const k=importantWeatherKey(e),old=importantWeatherCache.get(k);if(old&&Date.now()-old._at<15*60*1000)continue;if(!seen.has(k)){seen.add(k);unique.push(e)}}await Promise.all(unique.slice(0,10).map(async e=>{try{const lat=Number(e.latitude),lon=Number(e.longitude),u=new URL('https://api.open-meteo.com/v1/forecast');u.search=new URLSearchParams({latitude:String(lat),longitude:String(lon),current:'wind_speed_10m,wind_gusts_10m,wind_direction_10m,precipitation,rain',hourly:'precipitation_probability,precipitation,wind_speed_10m,wind_gusts_10m,wind_direction_10m',forecast_hours:'6',timezone:'America/Sao_Paulo',wind_speed_unit:'kmh',precipitation_unit:'mm'});const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw new Error(`Open-Meteo ${r.status}`);const o=await r.json(),h=o.hourly||{},rows=(h.time||[]).map((t,i)=>({t,prob:Number(h.precipitation_probability?.[i]||0),rain:Number(h.precipitation?.[i]||0),wind:Number(h.wind_speed_10m?.[i]||0),gust:Number(h.wind_gusts_10m?.[i]||0),dir:Number(h.wind_direction_10m?.[i]||0)}));const now=Date.now(),future=rows.filter(x=>new Date(x.t).getTime()>=now-10*60*1000).slice(0,3),cur=o.current||{};importantWeatherCache.set(importantWeatherKey(e),{_at:Date.now(),wind:Number(cur.wind_speed_10m||0),gust:Number(cur.wind_gusts_10m||0),dir:Number(cur.wind_direction_10m||0),rainNow:Number(cur.precipitation??cur.rain??0),rain3h:future.reduce((a,x)=>a+x.rain,0),prob3h:Math.max(0,...future.map(x=>x.prob))})}catch(err){console.warn('Falha enriquecimento evento importante',e.municipio,err)}}));renderImportantEvents();}
function importantOfficialEvents(){return operationalDefesaEvents().filter(e=>norm(e.status)==='ATIVO_OFICIAL'&&importantOfficialCurrent(e)).map(e=>{const text=e.resumo||'',t=importantNormText(text),extreme=norm(e.gravidade)==='EXTREME',granizo=t.includes('GRANIZO'),raios=t.includes('RAIOS')||t.includes('CONDICAO PARA RAIOS'),mov=t.includes('DESLOCANDO-SE'),sites=importantSitesFor(e.municipio),age=importantOfficialAgeHours(e),meteo=Number.isFinite(Number(e.latitude))&&Number.isFinite(Number(e.longitude))?importantWeatherCache.get(importantWeatherKey(e)):null;let score=extreme?100:0;if(granizo)score+=30;if(raios)score+=18;if(mov)score+=12;if(sites.ate4h)score+=10;if(age!=null)score+=Math.max(0,15-age*5);const mm=text.match(/(Deslocando-se[^.]*\.?)/i);const movementText=mm?mm[1]:null;return{kind:'oficial',score,urgent:extreme||granizo||(raios&&mov),municipio:e.municipio,lat:e.latitude,lon:e.longitude,time:importantTimeFromSummary(text),age,raios,mov,movementText,sites,text,gravidade:e.gravidade,tipo:e.tipo||e.titulo,fonte:e.fonte,urgencia:e.urgencia,meteo};}).filter(x=>x.urgent);}
function importantForecastEvents(){const regs=(forecastSpi&&forecastSpi.regioes)||[],now=Date.now();return regs.map(r=>{const ph=(r.previsao_horaria||[]).filter(x=>{const d=new Date(x.data_hora).getTime();return Number.isFinite(d)&&d>=now-10*60*1000&&d<=now+12*3600000});let first=null,idx=-1;for(let i=0;i<ph.length;i++){const x=ph[i],gust=Number(x.rajada_kmh||0),rain=Number(x.precipitacao_mm||0),code=Number(x.weather_code||0),storm=[95,96,99].includes(code);if(gust>=80||(storm&&gust>=60)||rain>=20){first=x;idx=i;break}}if(!first)return null;const sites=importantSitesFor(r.regiao),code=Number(first.weather_code||0),storm=[95,96,99].includes(code),gust=Number(first.rajada_kmh||0),wind=Number(first.vento_kmh||0),dir=Number(first.direcao_vento_graus||0),rain3h=ph.slice(idx,idx+3).reduce((a,x)=>a+Number(x.precipitacao_mm||0),0),prob3h=Math.max(0,...ph.slice(idx,idx+3).map(x=>Number(x.probabilidade_chuva||0)));return{kind:'previsao',score:80+gust,urgent:true,municipio:r.regiao,lat:r.latitude,lon:r.longitude,time:first.data_hora?new Date(first.data_hora).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):null,raios:false,storm,gust,wind,dir,rain3h,prob3h,sites,text:null,fonte:forecastSpi.fonte||'Open-Meteo'};}).filter(Boolean);}
function importantMessage(x){if(x.kind==='oficial'){const bits=[`<b>${esc(x.municipio)}</b>`,x.time?`<strong>emitido ${esc(x.time)}</strong>`:'',`🚨 ${esc(x.tipo||'Alerta oficial')}`];if(x.meteo){bits.push(`💨 ${x.meteo.wind.toFixed(0)} km/h ${esc(windCompass(x.meteo.dir))}`);bits.push(`🌬️ raj. ${x.meteo.gust.toFixed(0)} km/h`);bits.push(`🌧️ ${x.meteo.rain3h.toFixed(1)} mm/3h${x.meteo.prob3h?` • ${x.meteo.prob3h.toFixed(0)}%`:''}`)}if(x.raios)bits.push('⚡ raios confirmados');if(x.movementText)bits.push(`➡️ ${esc(x.movementText)}`);if(x.sites.total)bits.push(`📡 ${x.sites.total} sites`);if(x.sites.ate4h)bits.push(`🔋 <b>${x.sites.ate4h} ≤4h</b>`);bits.push(`<span class="important-source">Defesa Civil + Open-Meteo</span>`);return bits.filter(Boolean).join('<i>•</i>');}const bits=[`<b>${esc(x.municipio)}</b>`,x.time?`<strong>prev. ${esc(x.time)}</strong>`:'',x.storm?'⛈️ tempestade prevista':'⚠️ condição severa',`💨 ${x.wind.toFixed(0)} km/h ${esc(windCompass(x.dir))}`,`🌬️ raj. ${x.gust.toFixed(0)} km/h`,`🌧️ ${x.rain3h.toFixed(1)} mm/3h${x.prob3h?` • ${x.prob3h.toFixed(0)}%`:''}`];if(x.sites.total)bits.push(`📡 ${x.sites.total} sites`);if(x.sites.ate4h)bits.push(`🔋 <b>${x.sites.ate4h} ≤4h</b>`);bits.push(`<span class="important-source">${esc(x.fonte)}</span>`);return bits.join('<i>•</i>');}
function focusImportant(x){const lat=Number(x.lat),lon=Number(x.lon);if(Number.isFinite(lat)&&Number.isFinite(lon))map.setView([lat,lon],Math.max(map.getZoom(),9),{animate:true});}
function renderImportantEvents(){const el=document.getElementById('importantEventStrip'),track=document.getElementById('importantEventTrack'),lev=document.getElementById('importantEventLevel');if(!el||!track)return;const ev=[...importantOfficialEvents(),...importantForecastEvents()].sort((a,b)=>b.score-a.score).slice(0,8);if(!ev.length){el.hidden=true;track.innerHTML='';return;}el.hidden=false;if(lev)lev.textContent='URGENTE';const items=ev.map((x,i)=>`<button class="important-event-item" data-important-index="${i}" type="button">${importantMessage(x)}</button>`).join('');track.innerHTML=`<div class="important-event-run">${items}${items}</div>`;track.querySelectorAll('[data-important-index]').forEach(b=>b.addEventListener('click',()=>focusImportant(ev[Number(b.dataset.importantIndex)])));}

function weatherPopupHtml(e){const ativo=e.ameaca_ativa?'SIM':'NÃO';return `<div class="weather-popup"><b style="color:${weatherColor(e.nivel_risco)}">🌩️ ${esc(e.nivel_risco)}</b><br><b>${esc(e.municipio)}</b><br>Ameaça ativa: <b>${ativo}</b><br>Temperatura: ${esc(e.temperatura_c)} °C<br>Vento atual: ${esc(e.vento_atual_kmh)} km/h<br>Rajada: <b>${esc(e.rajada_kmh)} km/h</b><br>Chuva total: ${esc(e.chuva_total_mm)} mm<br>Prob. chuva: ${esc(e.probabilidade_chuva_pico)}%<br>Tempestade: ${e.tempestade?'SIM':'NÃO'}<br>Sites expostos: ${esc(e.sites_total)}<br>Sites ≤4h: ${esc(e.sites_ate_4h)}</div>`;}
function weatherDetailsHtml(e){const rows=[['Nível',e.nivel_risco],['Município',e.municipio],['Ameaça ativa',e.ameaca_ativa?'SIM':'NÃO'],['Condição',e.descricao],['Temperatura',e.temperatura_c!=null?`${e.temperatura_c} °C`:'—'],['Vento atual',e.vento_atual_kmh!=null?`${e.vento_atual_kmh} km/h`:'—'],['Direção vento',windCompass(e.direcao_vento_graus)],['Vento pico',e.vento_pico_kmh!=null?`${e.vento_pico_kmh} km/h`:'—'],['Rajada',e.rajada_kmh!=null?`${e.rajada_kmh} km/h`:'—'],['Fonte rajada',e.fonte_rajada],['Chuva atual',e.chuva_atual_mm!=null?`${e.chuva_atual_mm} mm`:'—'],['Chuva total',e.chuva_total_mm!=null?`${e.chuva_total_mm} mm`:'—'],['Prob. chuva',e.probabilidade_chuva_pico!=null?`${e.probabilidade_chuva_pico}%`:'—'],['Tempestade',e.tempestade?'SIM':'NÃO'],['Sites expostos',e.sites_total],['Sites ≤4h',e.sites_ate_4h]];return `<div class="panel-title">🌩️ Clima / tempestade</div><h3 class="weather-title" style="color:${weatherColor(e.nivel_risco)}">${esc(e.municipio)} • ${esc(e.nivel_risco)}</h3>${rows.map(r=>`<div class="row"><span>${esc(r[0])}</span><span>${esc(r[1]??'—')}</span></div>`).join('')}<div class="forecast-title">Próximas horas</div>${forecastHtml(e)}`;}
function renderWeather(){weatherLayer.clearLayers();const enabled=document.getElementById('weatherToggle')?.checked!==false;const ativos=weatherEvents.filter(e=>e.ameaca_ativa).length;const count=document.getElementById('weatherCount');if(count){count.textContent=`${ativos} ameaça${ativos===1?'':'s'}`;count.title=`${weatherEvents.length} municípios monitorados`;}if(!enabled)return;weatherEvents.forEach(e=>{const lat=Number(e.latitude),lon=Number(e.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))return;const color=weatherColor(e.nivel_risco);const active=Boolean(e.ameaca_ativa)||Boolean(e.tempestade);const marker=L.circleMarker([lat,lon],{radius:active?9:6,color:active?'#fff':color,weight:active?2:1,fillColor:color,fillOpacity:active?.9:.42,opacity:active?1:.72});marker.bindPopup(weatherPopupHtml(e));marker.bindTooltip(`🌩️ ${e.municipio||''} • ${e.nivel_risco||''} • rajada ${e.rajada_kmh??'—'} km/h`);marker.on('click',()=>{document.getElementById('details').innerHTML=weatherDetailsHtml(e);});marker.addTo(weatherLayer);});}

function renderForecastSpi(){const sel=document.getElementById('forecastSpiRegion'),sum=document.getElementById('forecastSpiSummary'),wins=document.getElementById('forecastSpiWindows'),src=document.getElementById('forecastSpiSource'),upd=document.getElementById('forecastSpiUpdated');if(!sel||!sum||!wins)return;const regs=forecastSpi.regioes||[];if(!regs.length){sum.textContent='Previsão meteorológica indisponível neste ciclo.';wins.innerHTML='';return}const old=sel.value;if(!sel.options.length||sel.options.length!==regs.length){sel.innerHTML=regs.map(r=>`<option>${esc(r.regiao)}</option>`).join('');if(old&&regs.some(r=>r.regiao===old))sel.value=old}const r=regs.find(x=>x.regiao===sel.value)||regs[0];sel.value=r.regiao;const a=r.atual||{},dir=windCompass(a.wind_direction_10m);sum.innerHTML=`<b>${esc(r.regiao)}</b><div class="forecast-spi-now"><span>🌡️ ${esc(a.temperature_2m??'—')} °C</span><span>💨 ${esc(a.wind_speed_10m??'—')} km/h • ${esc(dir)}</span><span>🌬️ raj. ${esc(a.wind_gusts_10m??'—')} km/h</span><span>${esc(weatherCodeLabel(a.weather_code))}</span></div>`;wins.innerHTML=['6h','12h','24h','48h','72h'].map(k=>{const w=(r.janelas||{})[k]||{};return `<div class="forecast-spi-window ${w.tempestade?'forecast-storm':''}"><b>${k}</b><span>🌧️ ${esc(w.chuva_mm??'—')} mm • ${esc(w.probabilidade_chuva_max??'—')}%</span><span>💨 ${esc(w.vento_max_kmh??'—')} km/h</span><span>🌬️ ${esc(w.rajada_max_kmh??'—')} km/h</span>${w.tempestade?'<strong>⚡ tempestade</strong>':''}</div>`}).join('');if(src)src.textContent=`Fonte: ${forecastSpi.fonte||'—'} • previsão independente das camadas operacionais`;if(upd)upd.textContent=forecastSpi.gerado_em?`Atualizado ${new Date(forecastSpi.gerado_em).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}`:'atualizado'}
async function loadForecastSpi(){try{const r=await fetch(`${FORECAST_SPI_DATA}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`Forecast SPI HTTP ${r.status}`);forecastSpi=await r.json();renderForecastSpi();renderImportantEvents();wlRenderPrevention();if(trajectoryMode)renderTrajectory()}catch(e){console.error('Falha Previsão SPI',e);const x=document.getElementById('forecastSpiSummary');if(x)x.textContent='Falha ao atualizar previsão meteorológica geral.'}}

async function loadWeather(){try{const r=await fetch(`${WEATHER_DATA}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`Weather HTTP ${r.status}`);const obj=await r.json();weatherMeta={gerado_em:obj.gerado_em,alertas_oficiais_ativos:obj.alertas_oficiais_ativos,fonte_alerta:obj.fonte_alerta};weatherEvents=Array.isArray(obj.eventos)?obj.eventos:[];renderWeather();renderClimateStrip();const c=document.getElementById('weatherCount');if(c&&obj.gerado_em)c.dataset.updated=obj.gerado_em;}catch(err){console.error('Falha Weather Risk',err);const c=document.getElementById('weatherCount');if(c)c.textContent='erro';const s=document.getElementById('climateStripStatus');if(s)s.textContent='erro ao atualizar';}}


function defesaPopupHtml(e){return `<div class="defesa-popup"><b style="color:#ef4444">🚨 DEFESA CIVIL</b><br><b>${esc(e.tipo||e.titulo)}</b><br>Município: <b>${esc(e.municipio)}</b><br>Gravidade: ${esc(e.gravidade)}<br>Urgência: ${esc(e.urgencia)}<br>Certeza: ${esc(e.certeza)}<br>Vigência: ${esc(e.vigencia)}<br><br>${esc(e.resumo)}</div>`;}
function defesaDetailsHtml(e){const rows=[['Tipo',e.tipo||e.titulo],['Município',e.municipio],['Gravidade',e.gravidade],['Urgência',e.urgencia],['Certeza',e.certeza],['Vigência',e.vigencia],['Status',e.status],['Fonte',e.fonte]];return `<div class="panel-title">🚨 Defesa Civil</div><h3 style="color:#ef4444">${esc(e.tipo||e.titulo)}</h3>${rows.map(r=>`<div class="row"><span>${esc(r[0])}</span><span>${esc(r[1]??'—')}</span></div>`).join('')}<p>${esc(e.resumo)}</p>`;}
function defesaOperationalRelevant(e){const t=importantNormText([e.tipo,e.titulo,e.evento,e.descricao,e.resumo,e.headline].filter(Boolean).join(' '));if(!t)return false;const excluded=['BAIXA UMIDADE','UMIDADE DO AR','ONDA DE CALOR','CALOR INTENSO','FRIO INTENSO','BAIXA TEMPERATURA','GEADA'];if(excluded.some(x=>t.includes(x)))return false;const relevant=['TEMPESTA','CHUVA INTENSA','CHUVAS INTENSAS','ALAGAMENTO','INUNDACAO','ENXURRADA','VENDAVAL','VENTO FORTE','RAJADA','GRANIZO','RAIOS','DESCARGA ATMOSFERICA','TORNADO','MICROEXPLOSAO','CICLONE','DESLIZAMENTO'];return relevant.some(x=>t.includes(x))||norm(e.gravidade)==='EXTREME';}
function operationalDefesaEvents(){return defesaEvents.filter(defesaOperationalRelevant)}
function renderDefesa(){defesaLayer.clearLayers();const enabled=document.getElementById('defesaToggle')?.checked!==false;const ops=operationalDefesaEvents();const count=document.getElementById('defesaCount');if(count){count.textContent=`${ops.length} operacional${ops.length===1?'':'is'}`;count.title=`${defesaEvents.length} município(s) no feed oficial; baixa umidade e eventos sem impacto direto ficam fora do mapa operacional`;}if(!enabled)return;ops.forEach(e=>{const lat=Number(e.latitude),lon=Number(e.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))return;const marker=L.circleMarker([lat,lon],{radius:8,color:'#ffffff',weight:2,fillColor:'#ef4444',fillOpacity:.95});marker.bindPopup(defesaPopupHtml(e));marker.bindTooltip(`🚨 ${e.tipo||e.titulo||'Defesa Civil'} • ${e.municipio||''}`);marker.on('click',()=>{document.getElementById('details').innerHTML=defesaDetailsHtml(e);});marker.addTo(defesaLayer);});}

function siteIsCritical(e){return Boolean(e.ate_4h)||norm(e.autonomia).includes('ATE 4H');}
function sitePopupHtml(e){return `<div class="site-popup"><b style="color:${siteIsCritical(e)?'#fb7185':'#7dd3fc'}">📡 ${esc(e.ufsite||e.site)}</b><br><b>${esc(e.municipio)}</b><br>Autonomia: <b>${esc(e.autonomia)}</b><br>Distribuidora: ${esc(e.distribuidora)}<br>DDD: ${esc(e.ddd)}</div>`;}
function siteDetailsHtml(e){const rows=[['Site',e.ufsite||e.site],['Município',e.municipio],['Autonomia',e.autonomia],['Faixa crítica',siteIsCritical(e)?'≤ 4h':'Acima de 4h'],['Distribuidora',e.distribuidora],['DDD',e.ddd],['IBGE',e.ibge]];return `<div class="panel-title">📡 Site</div><h3 style="color:${siteIsCritical(e)?'#fb7185':'#7dd3fc'}">${esc(e.ufsite||e.site)}</h3>${rows.map(r=>`<div class="row"><span>${esc(r[0])}</span><span>${esc(r[1]??'—')}</span></div>`).join('')}`;}
function renderSites(){sitesLayer.clearLayers();const enabled=document.getElementById('sitesToggle')?.checked===true;const count=document.getElementById('sitesCount');const crit=siteEvents.filter(siteIsCritical).length;if(count){count.textContent=`${siteEvents.length.toLocaleString('pt-BR')} • ${crit} ≤4h`;count.title='Sites totais • sites com autonomia até 4h';}if(!enabled)return;const z=map.getZoom();siteEvents.forEach(e=>{const lat=Number(e.latitude),lon=Number(e.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))return;const c=siteIsCritical(e),radius=z<=7?(c?3.0:2.0):z<=9?(c?4.2:2.8):(c?5.5:3.8);const marker=L.circleMarker([lat,lon],{radius,color:c?'#fecdd3':'#dbeafe',weight:c?1.0:.6,fillColor:c?'#fb7185':'#38bdf8',fillOpacity:c?.92:.58,opacity:.92});marker.bindPopup(sitePopupHtml(e));marker.bindTooltip(`📡 ${e.ufsite||e.site||''} • ${e.municipio||''} • ${e.autonomia||''}`);marker.on('click',()=>{document.getElementById('details').innerHTML=siteDetailsHtml(e);});marker.addTo(sitesLayer);});}
async function loadSites(){try{const r=await fetch(`${SITES_DATA}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`Sites HTTP ${r.status}`);const obj=await r.json();siteEvents=Array.isArray(obj.sites)?obj.sites:[];renderSites();renderMobileFocus();renderImportantEvents();}catch(err){console.error('Falha Sites GEO',err);const c=document.getElementById('sitesCount');if(c)c.textContent='erro';}}

