function commandForecastCandidates(){const now=Date.now(),out=[];(forecastSpi.regioes||[]).forEach(r=>{const rows=(r.previsao_horaria||[]).filter(x=>{const t=new Date(x.data_hora).getTime();return Number.isFinite(t)&&t>=now-10*60*1000&&t<=now+12*3600000});if(!rows.length)return;const worst=[...rows].sort((a,b)=>Number(b.rajada_kmh||0)-Number(a.rajada_kmh||0)||Number(b.probabilidade_chuva||0)-Number(a.probabilidade_chuva||0))[0];if(Number(worst.rajada_kmh||0)>=45||Number(worst.probabilidade_chuva||0)>=70||[95,96,99].includes(Number(worst.weather_code))){out.push({regiao:r.regiao,hora:worst.data_hora,rajada:worst.rajada_kmh,chuva:worst.precipitacao_mm,prob:worst.probabilidade_chuva,tempestade:[95,96,99].includes(Number(worst.weather_code))})}});return out.sort((a,b)=>Number(b.tempestade)-Number(a.tempestade)||Number(b.rajada)-Number(a.rajada)).slice(0,5)}
function commandBoardWindows(){return[{id:'agora',label:'AGORA',sub:'condição atual',from:-.5,to:.5},{id:'6h',label:'0–6H',sub:'prevenção imediata',from:0,to:6},{id:'12h',label:'6–12H',sub:'preparação regional',from:6,to:12},{id:'24h',label:'12–24H',sub:'planejamento',from:12,to:24},{id:'48h',label:'24–48H',sub:'antecipação',from:24,to:48}]}
function commandBackboneRoutesForRegion(name){const n=norm(name||'');const aliases=n==='LITORAL NORTE'?new Set(['CARAGUATATUBA','UBATUBA','SAO SEBASTIAO','ILHABELA']):new Set([n]);const ids=new Set();for(const f of (allFeatures||[])){const p=f.properties||{},cl=norm(p.cluster||''),ma=norm(p.municipio_a||''),mb=norm(p.municipio_b||'');if(cl===n||aliases.has(ma)||aliases.has(mb))ids.add(p.id_backbone||p.trecho||JSON.stringify([p.cabo,p.ponta_a,p.ponta_b]));}return ids.size}
function commandDddForRegion(name){const n=norm(name||'');const m={'OSASCO':'11','JUNDIAI':'11','SAO JOSE DOS CAMPOS':'12','LITORAL NORTE':'12','BAURU':'14','SOROCABA':'15','RIBEIRAO PRETO':'16','SAO JOSE DO RIO PRETO':'17','PRESIDENTE PRUDENTE':'18','ARACATUBA':'18','CAMPINAS':'19'};return m[n]||'—'}
function commandDddLabel(ddd,lead,items=[]){return lead?.regiao||items[0]?.regiao||(String(ddd)==='11'?'Grande Jundiaí / Grande Osasco':'Sem referência')}
function commandRegionHasProblem(x){return Boolean(x&&(x.storm||Number(x.rain||0)>=0.1||Number(x.gust||0)>=40||Number(x.prob||0)>=50))}
function commandSitesForDdd(ddd){const d=String(ddd),arr=(siteEvents||[]).filter(x=>String(x.ddd??'')===d&&(d!=='11'||x.escopo_spi_ddd11===true));return{total:arr.length,ate4h:arr.filter(siteIsCritical).length}}
function commandSitesForRegions(ddd,names=[]){const ns=new Set((names||[]).map(norm)),ln=new Set(['CARAGUATATUBA','SAO SEBASTIAO','UBATUBA','ILHABELA']);const arr=(siteEvents||[]).filter(x=>{if(String(x.ddd??'')!==String(ddd))return false;if(String(ddd)==='11'&&x.escopo_spi_ddd11!==true)return false;const m=norm(x.municipio);return ns.has(m)||(ns.has('LITORAL NORTE')&&ln.has(m))});return{total:arr.length,ate4h:arr.filter(siteIsCritical).length}}
function commandBoardRegionRows(win){const now=Date.now(),raw=[];for(const r of (forecastSpi?.regioes||[])){const rows=(r.previsao_horaria||[]).filter(z=>{const t=new Date(z.data_hora).getTime(),h=(t-now)/3600000;return Number.isFinite(t)&&h>=win.from&&h<win.to});if(!rows.length)continue;const rain=rows.reduce((n,z)=>n+Number(z.precipitacao_mm||0),0),gust=Math.max(0,...rows.map(z=>Number(z.rajada_kmh||0))),wind=Math.max(0,...rows.map(z=>Number(z.vento_kmh||0))),prob=Math.max(0,...rows.map(z=>Number(z.probabilidade_chuva||0))),temps=rows.map(z=>Number(z.temperatura_c??z.temperature_2m)).filter(Number.isFinite),temp=temps.length?Math.max(...temps):null,storm=rows.some(z=>[95,96,99].includes(Number(z.weather_code))),sites=importantSitesFor(r.regiao),score=(storm?60:0)+gust+rain*10+prob*.18+sites.ate4h*2;raw.push({regiao:r.regiao,ddd:commandDddForRegion(r.regiao),rain,gust,wind,prob,temp,storm,sites,backbone:commandBackboneRoutesForRegion(r.regiao),score})}const groups=new Map();for(const x of raw){if(!groups.has(x.ddd))groups.set(x.ddd,[]);groups.get(x.ddd).push(x)}const out=[];const wanted=['11','12','14','15','16','17','18','19'];for(const ddd of wanted){const items=groups.get(ddd)||[];items.sort((a,b)=>b.score-a.score);if(!items.length){out.push({ddd,regiao:ddd==='11'?'Grande Jundiaí / Grande Osasco':'Sem sinal no recorte',regioes:[],rain:0,gust:0,wind:0,prob:0,temp:null,storm:false,sites:commandSitesForDdd(ddd),backbone:0,score:0});continue}const affected=items.filter(commandRegionHasProblem),shown=affected.length?affected:items.slice(0,1),lead=shown[0],temps=shown.map(x=>x.temp).filter(Number.isFinite),siteScope=affected.length?commandSitesForRegions(ddd,shown.map(x=>x.regiao)):{ate4h:0,total:0};out.push({ddd,regiao:commandDddLabel(ddd,lead,shown),regioes:shown.map(x=>x.regiao),hasProblem:affected.length>0,rain:Math.max(0,...shown.map(x=>x.rain)),gust:Math.max(0,...shown.map(x=>x.gust)),wind:Math.max(0,...shown.map(x=>x.wind)),prob:Math.max(0,...shown.map(x=>x.prob)),temp:temps.length?Math.max(...temps):null,storm:shown.some(x=>x.storm),sites:siteScope,backbone:affected.length?shown.reduce((n,x)=>n+Number(x.backbone||0),0):0,score:affected.length?Math.max(...shown.map(x=>x.score))+Number(siteScope.ate4h||0)*2:0})}return out}
function commandBoardLevel(rows){if(!rows.length)return{key:'low',label:'BAIXO IMPACTO',icon:'☀️'};const x=rows[0];if((x.storm&&x.gust>=70)||x.gust>=80||x.rain>=20)return{key:'critical',label:'CHUVA + VENTO',icon:'⛈️'};if(x.storm||x.gust>=60||x.rain>=10)return{key:'high',label:'TEMPO SEVERO',icon:'🌩️'};if(x.gust>=45||x.rain>=3||x.prob>=70)return{key:'watch',label:'PONTO DE ATENÇÃO',icon:'🌧️'};return{key:'low',label:'BAIXO IMPACTO',icon:'🌤️'}}
function commandOfficialAlertTime(v){if(!v)return null;const s=String(v).trim();let d;if(/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}/.test(s))d=new Date(s.replace(' ','T')+':00-03:00');else d=new Date(s);const t=d.getTime();return Number.isFinite(t)?t:null}
function commandOfficialAlertsForWindow(win){const now=Date.now(),a=now+win.from*3600000,b=now+win.to*3600000,out=[];for(const e of [...(defesaEvents||[]),...(inmetAlerts||[])]){const st=commandOfficialAlertTime(e.inicio||e.data_inicio||e.vigencia_inicio||e.emitido_em),en=commandOfficialAlertTime(e.fim||e.validade_fim||e.data_fim||e.expira_em);if(win.id==='agora'){if((st==null||st<=now)&&(en==null||en>=now))out.push(e)}else if((st!=null&&st<b&&(en==null||en>=a))||(st==null&&en!=null&&en>=a&&en<b))out.push(e)}const embedded=[];for(const w of (weatherEvents||[])){const ao=w.alerta_oficial;if(ao&&typeof ao==='object')embedded.push({...ao,municipio:ao.municipio||w.municipio})}for(const e of embedded){const st=commandOfficialAlertTime(e.inicio||e.data_inicio||e.vigencia_inicio),en=commandOfficialAlertTime(e.fim||e.validade_fim||e.data_fim);if(win.id==='agora'?((st==null||st<=now)&&(en==null||en>=now)):((st!=null&&st<b&&(en==null||en>=a))))out.push(e)}const seen=new Set();return out.filter(e=>{const k=[e.fonte,e.id,e.tipo,e.titulo,e.municipio,e.inicio,e.fim].map(x=>String(x||'')).join('|');if(seen.has(k))return false;seen.add(k);return true}).sort((x,y)=>Number(y.severidade_rank||0)-Number(x.severidade_rank||0))}
function commandOfficialAlertHtml(a){const src=String(a.fonte||'DEFESA CIVIL').toUpperCase(),sev=a.severidade||a.gravidade||a.nivel||'AVISO',tipo=a.tipo||a.titulo||'Alerta oficial',mun=a.municipio||a.regiao||((a.abrangencia?.cidades||[]).slice(0,3).join(' • '))||'SP',inicio=a.inicio||a.data_inicio||'',fim=a.fim||a.validade_fim||a.data_fim||a.expira_em||'',wind=Array.isArray(a.vento_faixa_kmh)?` • vento ${a.vento_faixa_kmh.join('–')} km/h`:'',rain=Array.isArray(a.chuva_faixa_mmh)?` • chuva ${a.chuva_faixa_mmh.join('–')} mm/h`:'',haz=[a.granizo?'granizo':null,a.raios?'raios':null].filter(Boolean).join(' • '),period=(inicio||fim)?`<small>${inicio?`de ${esc(String(inicio).slice(5,16))}`:''}${fim?` até ${esc(String(fim).slice(5,16))}`:''}</small>`:'';return `<div class="command-board-alert"><b>🚨 ${esc(src)} • ${esc(sev)}</b><span>${esc(tipo)} • ${esc(mun)}${esc(wind)}${esc(rain)}${haz?` • ${esc(haz)}`:''}</span>${period}</div>`}
function commandBoardRowHtml(win){const rows=commandBoardRegionRows(win),lv=commandBoardLevel(rows),top=rows,maxRain=Math.max(0,...rows.map(x=>x.rain)),maxGust=Math.max(0,...rows.map(x=>x.gust)),maxWind=Math.max(0,...rows.map(x=>x.wind)),temps=rows.map(x=>x.temp).filter(Number.isFinite),maxTemp=temps.length?Math.max(...temps):null,maxProb=Math.max(0,...rows.map(x=>x.prob)),sites4=top.reduce((n,x)=>n+Number(x.sites.ate4h||0),0),alerts=commandOfficialAlertsForWindow(win).slice(0,3),hasEvent=alerts.length>0||rows.some(x=>x.storm||x.rain>0||x.gust>=40||x.prob>=50);const affected=top.map(x=>`DDD ${x.ddd} • ${x.regiao}`).filter(Boolean);const vis=`<div class="command-board-vision"><i>${lv.icon}</i><div><b>${lv.label}</b><span>Risco: <strong>${lv.key==='critical'?'crítico':lv.key==='high'?'alto':lv.key==='watch'?'atenção':'baixo'}</strong></span><small>${rows.length?`${rows.length} DDDs avaliados`:'sem sinal relevante no recorte'}</small>${affected.length?`<small class="command-affected"><b>DDDs potencialmente afetados:</b> ${affected.map(esc).join(' • ')}</small>`:''}</div></div>`;const alertHtml=alerts.length?alerts.map(commandOfficialAlertHtml).join(''):`<div class="command-board-ok">✓ Sem alerta oficial para esta janela</div>`;const regHtml=top.length?top.map(x=>`<div class="command-board-region"><b>DDD ${esc(x.ddd)} • ${esc(x.regiao)}${x.regioes?.length>1?` <small>+ ${x.regioes.slice(1).map(esc).join(' / ')}</small>`:''}</b><span>🌧 ${x.rain.toFixed(1)} mm</span><span>🌬 ${x.gust.toFixed(0)} km/h</span><span>🔋 ${x.sites.ate4h||0} ≤4h</span><span class="command-backbone-count">🧵 ${x.backbone||0} rotas</span></div>`).join(''):'<div class="command-board-empty">Sem região em atenção nesta janela.</div>';const met=`<div class="command-board-metrics"><div><small>CHUVA</small><b>${maxRain?maxRain.toFixed(1)+' mm':'0 mm'}</b></div><div><small>RAJADA</small><b>${maxGust?maxGust.toFixed(0)+' km/h':'—'}</b></div><div><small>VENTO</small><b>${maxWind?maxWind.toFixed(0)+' km/h':'—'}</b></div><div><small>TEMP.</small><b>${maxTemp!=null?maxTemp.toFixed(0)+'°C':'—'}</b></div><div><small>PROB.</small><b>${maxProb?maxProb.toFixed(0)+'%':'—'}</b></div></div>`;const impact=`<div class="command-board-impact"><div><b>${sites4}</b><span>sites ≤4h</span></div><div><b>${win.id==='agora'?energyEvents.length:'—'}</b><span>energia</span></div><div><b>${win.id==='agora'?fireEvents.length:'—'}</b><span>Fire</span></div></div>`;return `<div class="command-board-tr level-${lv.key} ${hasEvent?'has-event':'no-event'}"><div class="command-board-window"><b>${win.label}</b><span>${win.sub}</span></div><div>${vis}</div><div>${alertHtml}</div><div>${regHtml}</div><div>${met}</div><div>${impact}</div></div>`}
function renderCommandView(){const root=document.getElementById('commandView');if(!root)return;const snap=analystSnapshot(),top=analystTop(snap,5),ready=document.getElementById('commandReadiness');if(ready){ready.textContent=snap.readiness;ready.dataset.level=norm(snap.readiness)}const imp=[...importantOfficialEvents(),...importantForecastEvents()].sort((a,b)=>b.score-a.score)[0],urgent=document.getElementById('commandUrgentText');if(urgent)urgent.innerHTML=imp?importantMessage(imp):'<strong>Operação em monitoramento preventivo.</strong> Nenhum evento urgente consolidado neste ciclo.';const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};set('commandSummaryRegions',top.length);set('commandSummarySites',snap.exposedCritSites.length);set('commandSummaryEnergy',energyEvents.length);set('commandSummaryFire',fireEvents.length);set('commandSummaryAlerts',operationalDefesaEvents().length);const upd=document.getElementById('commandBoardUpdated');if(upd)upd.textContent='Atualizado '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'})+' • Brasília';const rows=document.getElementById('commandBoardRows');if(rows)rows.innerHTML=commandBoardWindows().map(commandBoardRowHtml).join('')}

