function showFireTab(){leaveRibeiraoMode();document.body.classList.remove('command-board-mobile');leaveTrajectoryMode();leaveMobileMode();document.getElementById('commandView').hidden=true;document.getElementById('mapView').hidden=false;document.getElementById('mapView').classList.add('fire-focus-mode');document.querySelectorAll('.fire-only-panel').forEach(x=>x.hidden=false);fireViewSaveToggles();fireViewApplyLayers();setActiveViewTab('tabFire');renderFireFocus();renderFireHistory();renderFireHistoryPanel();setTimeout(()=>map.invalidateSize(),60);renderFire()}
