function mobileViewApplyLayers(){const set=(id,v)=>{const e=document.getElementById(id);if(e)e.checked=v};set('fireToggle',false);set('weatherToggle',false);set('energyToggle',true);set('defesaToggle',false);set('sitesToggle',true);if(layer&&map.hasLayer(layer))map.removeLayer(layer);relatedBackboneLayer.clearLayers();renderFire();renderWeather();renderEnergy();renderDefesa();renderSites()}
