function trajectorySatelliteEnsurePane(){if(!map.getPane('trajectorySatellitePane')){const p=map.createPane('trajectorySatellitePane');p.style.zIndex='245';p.style.pointerEvents='none'}}
function trajectorySatelliteStatus(txt){const e=document.getElementById('trajectorySatelliteStatus');if(e)e.textContent=txt}
function trajectorySatelliteCreate(){trajectorySatelliteEnsurePane();if(trajectorySatelliteLayer){try{map.removeLayer(trajectorySatelliteLayer)}catch(e){}}trajectorySatelliteLayer=L.tileLayer.wms('https://gibs.earthdata.nasa.gov/wms/epsg3857/best/wms.cgi',{layers:'GOES-East_ABI_GeoColor',format:'image/png',transparent:true,version:'1.1.1',opacity:trajectorySatelliteOpacity,pane:'trajectorySatellitePane',attribution:'NASA GIBS • GOES-East/ABI',crossOrigin:true});trajectorySatelliteLayer.on('loading',()=>trajectorySatelliteStatus('NASA GIBS • carregando último frame GOES-East/ABI…'));trajectorySatelliteLayer.on('load',()=>trajectorySatelliteStatus('OBSERVADO • GOES-East/ABI • último frame disponível no NASA GIBS • GeoColor dia / IR multiespectral à noite'));trajectorySatelliteLayer.on('tileerror',()=>trajectorySatelliteStatus('Falha ao carregar um bloco da imagem de satélite; tentando atualizar.'));if(trajectorySatelliteOn&&trajectoryMode)trajectorySatelliteLayer.addTo(map);return trajectorySatelliteLayer}
function trajectorySatelliteApply(){const b=document.getElementById('trajectorySatelliteToggle');if(b){b.classList.toggle('active',trajectorySatelliteOn);b.textContent=trajectorySatelliteOn?'☁️ Nuvens ON':'☁️ Nuvens OFF'}if(!trajectorySatelliteLayer)trajectorySatelliteCreate();if(trajectorySatelliteOn&&trajectoryMode){if(!map.hasLayer(trajectorySatelliteLayer))trajectorySatelliteLayer.addTo(map)}else if(trajectorySatelliteLayer&&map.hasLayer(trajectorySatelliteLayer))map.removeLayer(trajectorySatelliteLayer)}
