function drawSelectedTrajectoryOverlay(x){
  const lat=Number(x.lat),lon=Number(x.lon);if(!Number.isFinite(lat)||!Number.isFinite(lon))return;
  const origin=[lat,lon];
  // Só desenhamos linha quando a própria fonte oficial informa deslocamento/destino.
  // Direção do vento continua nos dados do evento, mas não vira linha sobre o mapa.
  if(x.kind==='oficial'&&x.dst){
    const dst=x.dst,br=trajectoryBearing(origin,dst)??0;
    L.polyline([origin,dst],{color:'#ef4444',weight:6,opacity:.88,interactive:false}).addTo(trajectoryLayer);
    [.35,.68].forEach(f=>{const pt=trajectoryPointAlong(origin,dst,f);L.marker(pt,{icon:L.divIcon({className:'trajectory-chevron-wrap',html:`<div class="trajectory-chevron" style="transform:rotate(${br-90}deg)">➤</div>`,iconSize:[30,30],iconAnchor:[15,15]}),zIndexOffset:1500,interactive:false}).addTo(trajectoryLayer)});
    L.marker(dst,{icon:trajectoryLabelIcon(`<b>DESTINO: ${esc(x.dstName)}</b><small>deslocamento oficial</small>`,'destination'),zIndexOffset:1600,interactive:false}).addTo(trajectoryLayer)
  }
}
