function wlStormTitle(g){return [...g].sort((a,b)=>wlNum(b.rajada_kmh)-wlNum(a.rajada_kmh)).slice(0,4).map(e=>e.municipio).filter(Boolean).join(' • ')}
function wlStormMeta(g){const gust=Math.max(0,...g.map(e=>wlNum(e.rajada_kmh))),rain=Math.max(0,...g.map(e=>wlNum(e.chuva_total_mm))),low=g.reduce((n,e)=>n+wlSites(e).low,0);return {gust,rain,low}}

