function wlRiskBlobStyle(sev){return sev==='critical'?{color:'#ef233c',fill:'#ef233c',radius:52000,opacity:.22}:sev==='high'?{color:'#ff7a00',fill:'#ff7a00',radius:43000,opacity:.18}:{color:'#ffd000',fill:'#ffd000',radius:34000,opacity:.13}}
