function wlRenderRadarTimes(){const el=document.getElementById('weatherLabRadarTimes');if(!el)return;const frames=weatherLabRadarFrames;if(!frames.length){el.textContent='Sem frames de radar';return}const picks=[0,Math.floor((frames.length-1)*.33),Math.floor((frames.length-1)*.66),frames.length-1];el.innerHTML=[...new Set(picks)].map(i=>`<span>${new Date(frames[i].time*1000).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span>`).join('')}
